// Logs a sanitised summary to the n8n/Docker logs. Nothing is sent to Telegram users.
const e = $input.first().json;
const info = {
  workflow: e.workflow && e.workflow.name,
  failedNode: e.execution && e.execution.lastNodeExecuted,
  message: String((e.execution && e.execution.error && e.execution.error.message) || 'unknown').slice(0, 300),
  executionId: e.execution && e.execution.id
};
console.log('[WeatherBuddy][ErrorWorkflow]', JSON.stringify(info));
return [{ json: info }];
